    IntakeController_create_v1: {
        parameters: {
            query?: never;
            header: {
                /** @description 幂等键（1–128 位字母、数字、点、下划线、冒号或连字符） */
                "idempotency-key"?: string;
                /** @description SaaS 签发、绑定本次 intake 请求的一次性费用授权 JWS */
                "X-Site-Build-Budget-Grant": string;
                /** @description 可选：SaaS 签发的 understanding.run 授权；缺失时公司理解不触发，响应 understanding=not_started */
                "X-Execution-Budget-Grant"?: string;
            };
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["IntakeDto"];
            };
        };
        responses: {
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: components["schemas"]["IntakeResultDto"];
                    };
                };
            };
            /** @description 请求字段或 idempotency-key 非法 */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error: {
                            /** @enum {string} */
                            code: "INVALID_IDEMPOTENCY_KEY" | "VALIDATION_ERROR";
                            message: string;
                        };
                    };
                };
            };
            /** @description 费用授权缺失、非法或过期 */
            402: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error: {
                            /** @enum {string} */
                            code: "BUDGET_GRANT_REQUIRED" | "BUDGET_GRANT_INVALID" | "BUDGET_GRANT_EXPIRED";
                            message: string;
                        };
                    };
                };
            };
            /** @description 费用授权与 workspace/intake 请求不匹配 */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error: {
                            /** @enum {string} */
                            code: "BUDGET_GRANT_SCOPE_MISMATCH";
                            message: string;
                        };
                    };
                };
            };
            /** @description 幂等键复用冲突或 workspace 已有站点 */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error: {
                            /** @enum {string} */
                            code: "IDEMPOTENCY_KEY_REUSED" | "BUDGET_GRANT_REUSED" | "SITE_LIMIT_REACHED";
                            message: string;
                        };
                    };
                };
            };
            /** @description demo workflow 启动 ACK 不可用；有 key 时应同 key 重试 */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error: {
                            /** @enum {string} */
                            code: "DEMO_LAUNCH_UNAVAILABLE";
                            message: string;
                        };
                    };
                };
            };
            /** @description 费用授权验签或 Site Builder runtime 暂不可用 */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error: {
                            /** @enum {string} */
                            code: "BUDGET_GRANT_VERIFICATION_UNAVAILABLE" | "SITE_BUILD_RUNTIME_NOT_READY";
                            message: string;
                        };
                    };
                };
            };
        };
    };
